import json
for f in ['logs/eval_long_vla_only_seed45.json', 'logs/eval_long_adaptive_conformal_crm_norm0.2_tau0.25_seed45.json', 'logs/eval_object_crm_obs_only_norm0.05_seed46.json', 'logs/eval_goal_adaptive_conformal_crm_norm0.2_tau0.25_seed45.json']:
    try:
        d = json.load(open(f))
        top_keys = list(d.keys())[:10]
        print(f'{f}: keys={top_keys}')
        # Try to compute SR from per-task results
        if 'per_task' in d:
            tasks = d['per_task']
            total_succ = sum(t.get('successes',0) for t in tasks.values())
            total_ep = sum(t.get('total',0) for t in tasks.values())
            print(f'  Computed: SR={total_succ/total_ep:.1%}, {total_succ}/{total_ep}')
        elif isinstance(d, dict):
            # Maybe results are at top level as task_name: {successes, total}
            total_succ = 0; total_ep = 0
            for k,v in d.items():
                if isinstance(v, dict) and 'successes' in v:
                    total_succ += v['successes']
                    total_ep += v.get('total', v.get('episodes', 20))
            if total_ep > 0:
                print(f'  Computed: SR={total_succ/total_ep:.1%}, {total_succ}/{total_ep}')
    except Exception as e:
        print(f'{f}: ERROR {e}')
"
